#include <fstream>
#include <iostream>
#include <string>

int main() {
    std::string line;
    std::getline(std::cin, line);
    {
        std::ofstream out("note.txt");
        out << line << std::endl;
    }
    std::ifstream in("note.txt");
    std::string restored;
    std::getline(in, restored);
    std::cout << restored << std::endl;
    return 0;
}
